-- Reviewed source facts, without automatic journal postings or inferred classifications.
CREATE TABLE investment_import_batches(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('investment','valuation','transaction')),request_key TEXT NOT NULL UNIQUE,rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),created_by TEXT NOT NULL REFERENCES "user"(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE investment_import_refs(kind TEXT NOT NULL CHECK(kind IN ('investment','valuation','transaction')),source_ref TEXT NOT NULL,record_id TEXT NOT NULL,batch_id TEXT NOT NULL REFERENCES investment_import_batches(id),PRIMARY KEY(kind,source_ref),UNIQUE(kind,record_id));
CREATE TRIGGER investment_import_validate BEFORE INSERT ON investment_import_batches BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 100 THEN RAISE(ABORT,'invalid batch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.id') IS NOT 'text' OR length(json_extract(r.value,'$.id')) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.sourceRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.sourceRef'))) NOT BETWEEN 1 AND 128 OR json_extract(r.value,'$.sourceRef') IS NOT trim(json_extract(r.value,'$.sourceRef'))) THEN RAISE(ABORT,'invalid reference') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r GROUP BY json_extract(r.value,'$.sourceRef') HAVING count(*)>1) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r JOIN investment_import_refs x ON x.kind=NEW.kind AND x.source_ref=json_extract(r.value,'$.sourceRef')) THEN RAISE(ABORT,'source reference conflict') END;
 SELECT CASE WHEN NEW.kind='investment' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE substr(json_extract(r.value,'$.sourceRef'),1,3)='id:' OR json_type(r.value,'$.name') IS NOT 'text' OR length(trim(json_extract(r.value,'$.name'))) NOT BETWEEN 1 AND 200 OR json_type(r.value,'$.assetClass') IS NOT 'text' OR length(trim(json_extract(r.value,'$.assetClass'))) NOT BETWEEN 1 AND 100 OR json_extract(r.value,'$.status') NOT IN ('active','closed') OR json_type(r.value,'$.status') IS NOT 'text' OR json_type(r.value,'$.currency') IS NOT 'text' OR length(json_extract(r.value,'$.currency'))<>3 OR json_extract(r.value,'$.currency') NOT GLOB '[A-Z][A-Z][A-Z]') THEN RAISE(ABORT,'invalid investment') END;
 SELECT CASE WHEN NEW.kind IN ('valuation','transaction') AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM investments i WHERE i.id=json_extract(r.value,'$.investmentId') AND (json_extract(r.value,'$.investmentRef')='id:'||i.id OR (substr(json_extract(r.value,'$.investmentRef'),1,3)<>'id:' AND EXISTS(SELECT 1 FROM investment_import_refs x WHERE x.kind='investment' AND x.record_id=i.id AND x.source_ref=json_extract(r.value,'$.investmentRef')))) AND i.name=json_extract(r.value,'$.investmentName') AND i.asset_class=json_extract(r.value,'$.investmentAssetClass') AND i.currency=json_extract(r.value,'$.investmentCurrency') AND i.status=json_extract(r.value,'$.investmentStatus'))) THEN RAISE(ABORT,'investment changed; review again') END;
 SELECT CASE WHEN NEW.kind IN ('valuation','transaction') AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.amountMinor') IS NOT 'text' OR json_extract(r.value,'$.amountMinor') GLOB '*[^0-9]*' OR length(json_extract(r.value,'$.amountMinor')) NOT BETWEEN 1 AND 16 OR CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) NOT BETWEEN CASE WHEN NEW.kind='valuation' THEN 0 ELSE 1 END AND 9007199254740991 OR CAST(CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) AS TEXT) IS NOT json_extract(r.value,'$.amountMinor') OR (json_type(r.value,'$.notes') IS NOT 'null' AND (json_type(r.value,'$.notes') IS NOT 'text' OR length(trim(json_extract(r.value,'$.notes'))) NOT BETWEEN 1 AND 2000))) THEN RAISE(ABORT,'invalid amount or notes') END;
 SELECT CASE WHEN NEW.kind='valuation' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.valuationDate') IS NOT 'text' OR date(json_extract(r.value,'$.valuationDate'),'+0 days') IS NOT json_extract(r.value,'$.valuationDate') OR json_type(r.value,'$.basis') IS NOT 'text' OR length(trim(json_extract(r.value,'$.basis'))) NOT BETWEEN 1 AND 200 OR (json_type(r.value,'$.source') IS NOT 'null' AND (json_type(r.value,'$.source') IS NOT 'text' OR length(trim(json_extract(r.value,'$.source'))) NOT BETWEEN 1 AND 200))) THEN RAISE(ABORT,'invalid valuation') END;
 SELECT CASE WHEN NEW.kind='transaction' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.transactionDate') IS NOT 'text' OR date(json_extract(r.value,'$.transactionDate'),'+0 days') IS NOT json_extract(r.value,'$.transactionDate') OR json_type(r.value,'$.transactionType') IS NOT 'text' OR length(trim(json_extract(r.value,'$.transactionType'))) NOT BETWEEN 1 AND 100 OR (json_type(r.value,'$.reference') IS NOT 'null' AND (json_type(r.value,'$.reference') IS NOT 'text' OR length(trim(json_extract(r.value,'$.reference'))) NOT BETWEEN 1 AND 200))) THEN RAISE(ABORT,'invalid transaction') END;
END;
CREATE TRIGGER investment_import_apply AFTER INSERT ON investment_import_batches BEGIN
 INSERT INTO investments(id,name,asset_class,currency,status,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.name'),json_extract(r.value,'$.assetClass'),json_extract(r.value,'$.currency'),json_extract(r.value,'$.status'),NEW.created_by FROM json_each(NEW.rows_json) r WHERE NEW.kind='investment';
 INSERT INTO investment_valuations(id,investment_id,valuation_date,amount_minor,currency,basis,source,notes,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.investmentId'),json_extract(r.value,'$.valuationDate'),CAST(json_extract(r.value,'$.amountMinor') AS INTEGER),json_extract(r.value,'$.investmentCurrency'),json_extract(r.value,'$.basis'),json_extract(r.value,'$.source'),json_extract(r.value,'$.notes'),NEW.created_by FROM json_each(NEW.rows_json) r WHERE NEW.kind='valuation';
 INSERT INTO investment_transactions(id,investment_id,transaction_date,transaction_type,amount_minor,reference,notes,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.investmentId'),json_extract(r.value,'$.transactionDate'),json_extract(r.value,'$.transactionType'),CAST(json_extract(r.value,'$.amountMinor') AS INTEGER),json_extract(r.value,'$.reference'),json_extract(r.value,'$.notes'),NEW.created_by FROM json_each(NEW.rows_json) r WHERE NEW.kind='transaction';
 INSERT INTO investment_import_refs(kind,source_ref,record_id,batch_id) SELECT NEW.kind,json_extract(r.value,'$.sourceRef'),json_extract(r.value,'$.id'),NEW.id FROM json_each(NEW.rows_json) r;
END;
CREATE TRIGGER investment_import_no_update BEFORE UPDATE ON investment_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER investment_import_no_delete BEFORE DELETE ON investment_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER investment_import_ref_no_update BEFORE UPDATE ON investment_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
CREATE TRIGGER investment_import_ref_no_delete BEFORE DELETE ON investment_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
